mapper.select:
select id, user_id, vehicle_id, browse_time
from carsale_browse_history

    and user_id = #{userId}
    and vehicle_id = #{vehicleId}

order by browse_time desc

select vehicle_id
from (
    select distinct vehicle_id, max(browse_time) as max_time
    from carsale_browse_history
    where user_id = #{userId}
    group by vehicle_id
    order by max_time desc
    limit #{limit}
) as t
